template <class _TYPE>
inline const _TYPE& _cpp_min(_TYPE _X, _TYPE _Y)
{
    return (_Y < _X ? _Y : _X);
}

template <class _TYPE>
inline const _TYPE& _cpp_max(_TYPE _X, _TYPE _Y)
{
    return (_X < _Y ? _Y : _X);
}

template <class _TYPE>
inline const _TYPE& _cpp_limit(_TYPE _Lo, _TYPE _V, _TYPE _Hi)
{
    return (_V < _Lo ? _Lo : (_Hi < _V ? _Hi : _V));
}

